CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
ALTER FUNCTION public.has_role(uuid, public.app_role) SET SCHEMA private;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.has_role(uuid, public.app_role) TO authenticated;
ALTER POLICY "Admins manage roles" ON public.user_roles USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage settings" ON public.site_settings USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage homepage" ON public.homepage_content USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage services" ON public.services USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage elevators" ON public.elevator_types USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage projects" ON public.projects USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage project images" ON public.project_images USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage testimonials" ON public.testimonials USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage faqs" ON public.faqs USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage quotes" ON public.quote_requests USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage attachments" ON public.quote_attachments USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage notes" ON public.quote_notes USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins manage messages" ON public.contact_messages USING (private.has_role(auth.uid(),'admin')) WITH CHECK (private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins upload site media" ON storage.objects WITH CHECK (bucket_id='public-site-media' AND private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins update site media" ON storage.objects USING (bucket_id='public-site-media' AND private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins delete site media" ON storage.objects USING (bucket_id='public-site-media' AND private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins read quote files" ON storage.objects USING (bucket_id='quote-attachments' AND private.has_role(auth.uid(),'admin'));
ALTER POLICY "Admins delete quote files" ON storage.objects USING (bucket_id='quote-attachments' AND private.has_role(auth.uid(),'admin'));